import Link from "next/link"
import type { ReactNode } from "react"

import { Badge } from "@/components/ui/badge"
import { Button } from "@/components/ui/button"
import { cn } from "@/lib/utils"

type CockpitNav = "dashboard" | "chat"

export function CockpitShell({
  active,
  trailing,
  children,
}: {
  active: CockpitNav
  trailing?: ReactNode
  children: ReactNode
}) {
  return (
    <div className="flex h-dvh min-h-0 flex-col overflow-hidden bg-background">
      <header className="flex shrink-0 items-center gap-3 border-b border-border px-4 py-2.5">
        <span className="text-sm font-medium">Stockout</span>
        <nav className="flex items-center gap-1" aria-label="Cockpit">
          <NavLink href="/dashboard" active={active === "dashboard"}>
            Dashboard
          </NavLink>
          <NavLink href="/chat" active={active === "chat"}>
            Chat
          </NavLink>
        </nav>
        <Badge variant="outline">rehearsal</Badge>
        <span className="text-muted-foreground text-sm">Munich plant</span>
        {trailing ? (
          <div className="ml-auto flex min-w-0 items-center gap-2">{trailing}</div>
        ) : null}
      </header>
      {children}
    </div>
  )
}

function NavLink({
  href,
  active,
  children,
}: {
  href: string
  active: boolean
  children: ReactNode
}) {
  return (
    <Button
      nativeButton={false}
      size="sm"
      variant={active ? "default" : "ghost"}
      className={cn(!active && "text-muted-foreground")}
      render={<Link href={href} aria-current={active ? "page" : undefined} />}
    >
      {children}
    </Button>
  )
}

"use client"

import { GitPullRequestIcon } from "lucide-react"

import { Alert, AlertDescription, AlertTitle } from "@/components/ui/alert"
import { Badge } from "@/components/ui/badge"
import { Button } from "@/components/ui/button"
import { ButtonGroup } from "@/components/ui/button-group"
import {
  Table,
  TableBody,
  TableCaption,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from "@/components/ui/table"
import {
  CALL_TURNS,
  CANDIDATES,
  CASE_FILES,
  PR_PATH,
  SCRIPT,
  type ScriptStep,
  type StockStatus,
} from "@/lib/case-001"
import { cn } from "@/lib/utils"

export type WorkingTab = "files" | "results"

export function WorkingPane({
  visible,
  tab,
  onTabChange,
}: {
  visible: number
  tab: WorkingTab
  onTabChange: (tab: WorkingTab) => void
}) {
  const visibleSteps = SCRIPT.slice(0, visible)
  const visibleIds = new Set(visibleSteps.map((step) => step.id))
  const files = CASE_FILES.filter((file) => visibleIds.has(file.afterId))
  const resultKind = resultKindFor(visibleSteps)

  return (
    <aside className="flex min-h-0 min-w-0 flex-1 flex-col border-l border-border bg-card">
      <div className="flex h-11 shrink-0 items-center gap-1 border-b border-border px-3">
        <ButtonGroup>
          <Button
            size="sm"
            variant={tab === "files" ? "default" : "ghost"}
            aria-pressed={tab === "files"}
            onClick={() => onTabChange("files")}
          >
            Files
          </Button>
          <Button
            size="sm"
            variant={tab === "results" ? "default" : "ghost"}
            aria-pressed={tab === "results"}
            onClick={() => onTabChange("results")}
          >
            Results
          </Button>
        </ButtonGroup>
      </div>
      {tab === "files" ? (
        <FileList files={files} />
      ) : (
        <ResultsPanel kind={resultKind} />
      )}
    </aside>
  )
}

function FileList({
  files,
}: {
  files: readonly (typeof CASE_FILES)[number][]
}) {
  if (files.length === 0) {
    return (
      <p className="text-muted-foreground p-4 text-sm">No artifacts yet.</p>
    )
  }

  return (
    <ul className="flex flex-col p-2">
      {files.map((file) => (
        <li
          key={file.name}
          className="flex items-center gap-3 px-3 py-2 text-sm"
        >
          <span className="text-muted-foreground w-8 shrink-0 font-mono text-xs">
            {file.ext}
          </span>
          <span className="min-w-0 flex-1 truncate font-mono">{file.name}</span>
        </li>
      ))}
    </ul>
  )
}

function ResultsPanel({ kind }: { kind: ResultKind }) {
  if (kind === "call") {
    return <CallResult />
  }
  if (kind === "compare") {
    return <ClaimRecordTable />
  }
  if (kind === "decision") {
    return <DecisionResult />
  }
  return (
    <p className="text-muted-foreground p-4 text-sm">No results yet.</p>
  )
}

function CallResult() {
  return (
    <div className="flex min-h-0 flex-1 flex-col">
      <div className="flex h-11 shrink-0 items-center justify-between gap-3 border-b border-border px-4">
        <div className="flex items-center gap-2">
          <span className="bg-primary size-2 shrink-0" aria-hidden />
          <span className="text-sm font-medium">Call connected 0:22</span>
        </div>
        <div className="flex items-center gap-3">
          <span className="text-muted-foreground font-mono text-xs">
            {CANDIDATES[0].phone}
          </span>
          <Button size="sm" type="button">
            End
          </Button>
        </div>
      </div>
      <div className="flex flex-1 flex-col gap-4 overflow-y-auto p-4">
        {CALL_TURNS.map((turn) => (
          <div key={turn.speaker} className="flex flex-col gap-1">
            <span className="text-muted-foreground font-mono text-xs">
              {turn.speaker}
            </span>
            <p className="text-sm text-pretty">{turn.text}</p>
          </div>
        ))}
      </div>
      <div className="text-muted-foreground flex h-12 shrink-0 items-center gap-4 border-t border-border px-4 font-mono text-xs">
        <span className="uppercase">Claim</span>
        <span>price · unknown</span>
        <span>stock · unclear</span>
        <span>cert · unknown</span>
      </div>
    </div>
  )
}

function ClaimRecordTable() {
  const rows = CANDIDATES.filter((candidate) => candidate.claimUnit)

  return (
    <div className="min-h-0 flex-1 overflow-auto p-3">
      <Table>
        <TableCaption>
          Claim values sit next to the Supplier Record. Claims are not facts.
        </TableCaption>
        <TableHeader>
          <TableRow>
            <TableHead>Candidate</TableHead>
            <TableHead>Record unit</TableHead>
            <TableHead>Claim unit</TableHead>
            <TableHead>stock_status</TableHead>
          </TableRow>
        </TableHeader>
        <TableBody>
          {rows.map((candidate) => (
            <TableRow key={candidate.name}>
              <TableCell>{candidate.name}</TableCell>
              <TableCell className="font-mono tabular-nums">
                {candidate.recordUnit}
              </TableCell>
              <TableCell className="font-mono tabular-nums">
                {candidate.claimUnit}
              </TableCell>
              <TableCell>
                <Badge variant={stockBadgeVariant(candidate.stockStatus!)}>
                  {candidate.stockStatus}
                </Badge>
              </TableCell>
            </TableRow>
          ))}
        </TableBody>
      </Table>
    </div>
  )
}

function DecisionResult() {
  return (
    <div className="flex flex-col gap-3 p-4">
      <Alert>
        <GitPullRequestIcon />
        <AlertTitle>Decision ready for merge</AlertTitle>
        <AlertDescription>
          SPLIT 20% SKF air + 80% FAG sea. A human approves by merging{" "}
          <span className="font-mono">{PR_PATH}</span>.
        </AlertDescription>
      </Alert>
    </div>
  )
}

type ResultKind = "empty" | "call" | "compare" | "decision"

function resultKindFor(steps: ScriptStep[]): ResultKind {
  const kinds = new Set(steps.map((step) => step.kind))
  if (kinds.has("decision")) {
    return "decision"
  }
  if (kinds.has("deltas") || kinds.has("strategy")) {
    return "compare"
  }
  if (kinds.has("outreach") || kinds.has("claims")) {
    return "call"
  }
  return "empty"
}

function stockBadgeVariant(
  status: StockStatus
): "secondary" | "destructive" | "outline" {
  if (status === "in_stock_allocated" || status === "unavailable") {
    return "destructive"
  }
  if (status === "free_in_stock") {
    return "secondary"
  }
  return "outline"
}

export function paneForVisible(visible: number): WorkingTab {
  const kind = resultKindFor(SCRIPT.slice(0, visible))
  return kind === "empty" ? "files" : "results"
}

export function stageBadgeVariant(
  stage: "open" | "calling" | "decided"
): "default" | "secondary" | "outline" {
  if (stage === "open") {
    return "default"
  }
  if (stage === "calling") {
    return "secondary"
  }
  return "outline"
}

export { cn }

