export function CockpitChat() {
  const [started, setStarted] = useState(false)
  const [visible, setVisible] = useState(0)
  const [tab, setTab] = useState<WorkingTab>("files")
  const [tabPinned, setTabPinned] = useState(false)
  const phase: Phase = !started
    ? "idle"
    : visible >= SCRIPT.length
      ? "done"
      : "running"

  useEffect(() => {
    if (!started) {
      return
    }
    if (visible >= SCRIPT.length) {
      return
    }
    const id = window.setInterval(() => {
      setVisible((count) => Math.min(count + 1, SCRIPT.length))
    }, TICK_MS)
    return () => window.clearInterval(id)
  }, [started, visible])

  useEffect(() => {
    if (tabPinned) {
      return
    }
    setTab(paneForVisible(visible))
  }, [visible, tabPinned])

  const currentStep =
    phase === "idle"
      ? "Awaiting launch"
      : visible === 0
        ? "Launching"
        : SCRIPT[Math.min(visible, SCRIPT.length) - 1].stepName

  function launch() {
    const skipTicks = window.matchMedia(
      "(prefers-reduced-motion: reduce)"
    ).matches
    setStarted(true)
    setVisible(skipTicks ? SCRIPT.length : 0)
    setTabPinned(false)
  }

  function reset() {
    setStarted(false)
    setVisible(0)
    setTab("files")
    setTabPinned(false)
  }

  return (
    <CockpitShell
      active="chat"
      trailing={
        <p
          className="flex items-center gap-2 truncate text-sm text-muted-foreground tabular-nums"
          aria-live="polite"
        >
          {phase === "running" ? <DotLoader /> : null}
          {currentStep}
          <span className="text-muted-foreground/70">
            {" "}
            · {visible} Event{visible === 1 ? "" : "s"}
          </span>
        </p>
      }
    >
      <div className="flex h-11 shrink-0 items-center justify-between gap-4 border-b border-border px-4">
        <div className="flex items-center gap-4 text-sm">
          <span className="font-mono">{INCIDENT.caseId}</span>
          <span className="text-muted-foreground">{INCIDENT.partId}</span>
          <span>{INCIDENT.lineStopDays} days to line stop</span>
        </div>
        <span className="text-muted-foreground text-sm">Devin session</span>
      </div>
      <div className="flex min-h-0 flex-1">
        <div className="flex min-h-0 min-w-0 flex-[58] flex-col">
          <Conversation className="min-h-0">
            <ConversationContent>
              <UserIncident />

              {SCRIPT.slice(0, visible).map((step, index) => (
                <AssistantTurn
                  key={step.id}
                  step={step}
                  latest={index === visible - 1 && phase === "running"}
                />
              ))}

              {phase === "running" ? (
                <div className="flex items-center gap-2 text-muted-foreground text-sm">
                  <DotLoader />
                  <span>{currentStep}</span>
                </div>
              ) : null}
            </ConversationContent>
            <ConversationScrollButton />
          </Conversation>
          <Composer phase={phase} onLaunch={launch} onReset={reset} />
        </div>
        <WorkingPane
          visible={visible}
          tab={tab}
          onTabChange={(next) => {
            setTabPinned(true)
            setTab(next)
          }}
        />
      </div>
    </CockpitShell>
  )
}

